package com.hirehub.entity;

import jakarta.persistence.Column;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.MappedSuperclass;

import java.util.Objects;

/**
 * Surrogate identity shared by every entity with a single-column primary key.
 *
 * <p>{@code GenerationType.IDENTITY} matches the {@code GENERATED BY DEFAULT AS IDENTITY}
 * columns in migration V1. ALTERNATIVE: a sequence with an allocation size, which lets
 * Hibernate batch inserts. Rejected for now because this system has no bulk-insert path;
 * IDENTITY keeps the schema readable and matches how the tables are defined.</p>
 *
 * <p><b>equals/hashCode:</b> based on the id, with a constant hash code. This is the
 * standard JPA-safe formulation: an entity's hash must not change when a generated id is
 * assigned on flush, otherwise the entity gets lost inside any {@code HashSet} it was added
 * to beforehand. Two unsaved instances are never equal.</p>
 */
@MappedSuperclass
public abstract class BaseEntity {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    @Column(name = "id", nullable = false, updatable = false)
    private Long id;

    public Long getId() {
        return id;
    }

    protected void setId(Long id) {
        this.id = id;
    }

    /** True before the entity has been persisted. Useful in services and tests. */
    public boolean isNew() {
        return id == null;
    }

    @Override
    public boolean equals(Object other) {
        if (this == other) {
            return true;
        }
        // Not getClass(): Hibernate may hand back a proxy subclass for a lazy association.
        if (!(other instanceof BaseEntity that)) {
            return false;
        }
        return id != null && Objects.equals(id, that.id);
    }

    @Override
    public int hashCode() {
        return getClass().hashCode();
    }
}
